/*
# Seed KPI Dashboard Data

Inserts all 7 business areas, their KPIs with definitions/formulas/decisions,
sample current values with targets, monthly series, and breakdowns.
*/

-- ============================================================
-- AREAS
-- ============================================================
ON CONFLICT (slug) DO NOTHING;

-- Helper: get area IDs
DO $$ DECLARE
  v_ventas uuid; v_rombo uuid; v_miauto uuid; v_postv uuid; v_calidad uuid; v_rrhh uuid; v_finan uuid;
BEGIN
  SELECT id INTO v_ventas FROM areas WHERE slug = 'ventas-0km';
  SELECT id INTO v_rombo FROM areas WHERE slug = 'plan-rombo';
  SELECT id INTO v_miauto FROM areas WHERE slug = 'mi-auto-ya';
  SELECT id INTO v_postv FROM areas WHERE slug = 'postventa';
  SELECT id INTO v_calidad FROM areas WHERE slug = 'calidad';
  SELECT id INTO v_rrhh FROM areas WHERE slug = 'rrhh';
  SELECT id INTO v_finan FROM areas WHERE slug = 'admn-finanzas';

  -- VENTAS 0 KM

  -- PLAN ROMBO

  -- MI AUTO YA!

  -- POSTVENTA

  -- CALIDAD

  -- RRHH

  -- ADM. Y FINANZAS
END $$;